message.content:
{
  "pitches": [
    {
      "title": "금강의 잔류 사념과 철쇄아의 공명",
      "situation": "플레이어가 금강의 사념이 깃든 통로를 지나던 중, 셋쇼마루의 검(철쇄아)에 깃든 '타인을 지키려는 마음'이 금강의 죽음과 관련된 슬픈 잔류 사념과 충돌하여 강력한 마력 폭풍이 발생합니다. 통로가 무너지기 시작하며 플레이어의 정신을 흔드는 환각이 발생합니다.",
      "actions": [
        {
          "action": "이누야샤의 온정으로 공명 억제",
          "consequence": "이누야샤의 '온정적인 본심'을 끌어내어 마력 폭풍을 진정시킵니다. 성공 시 플레이어의 정신 오염을 막고 다음 구역에서 1회 행동력 추가를 얻습니다.",
          "card": "이누야샤",
          "effects": "swift: 90, action_speed: 2%"
        },
        {
          "action": "가영의 화살로 사념 소멸",
          "consequence": "사혼의 기운을 감지하는 가영의 화살로 잔류 사념을 강제로 태워버립니다. 성공 시 통로를 즉시 확보하지만, 사념의 반동으로 다음 전투에서 1회 행동력 소모가 1 증가합니다.",
          "card": "가영",
          "effects": "damage_percent: 15%"
        },
        {
          "action": "묘가의 지식으로 경로 우회",
          "consequence": "묘가의 지식을 빌려 폭풍이 잦아들 때까지 안전한 틈새를 찾습니다. 성공 시 대미지 없이 통과하나, 묘가의 겁먹은 반응으로 인해 이동 속도가 감소합니다.",
          "card": "묘가",
          "effects": "move_speed: 5%"
        }
      ],
      "followup": "성공 시 행동력 +1 / 실패 시 행동력 -2",
      "canonUse": "금강의 머리 구조를 통한 통로 이동 및 철쇄아의 마음 반응 설정 활용.",
      "weakness": "이누야샤의 '온정'이라는 추상적 개념을 수치화하기 어렵고, 행동력 보너스가 전투 외 상황에서만 유효할 수 있음."
    },
    {
      "title": "미륵의 풍혈: 삼켜지는 생명력",
      "situation": "플레이어가 미륵과 동행하던 중, 주변 환경에 미륵의 '풍혈'이 발현됩니다. 이는 단순한 흡혈이 아니라 주변의 생명력을 빨아들이는 저주로, 플레이어의 체력을 지속적으로 깎아내리며 동시에 주변 적들을 강화시킵니다.",
      "actions": [
        {
          "action": "풍혈의 흐름을 몸으로 막음",
          "consequence": "미륵의 저주를 일시적으로 견뎌내며 적들의 강화 효과를 무효화합니다. 성공 시 플레이어의 최대 체력이 일시적으로 감소하지만, 다음 전투에서 방어력이 상승합니다.",
          "card": "미륵",
          "effects": "damage_reduction: 10%, max_health_percent: -5%"
        },
        {
          "action": "산고의 비래골로 결계 생성",
          "consequence": "퇴마사 산고의 비래골을 사용하여 풍혈의 확산을 차단합니다. 성공 시 체력 감소를 멈추고 주변 적의 공격력을 낮춥니다.",
          "card": "산고",
          "effects": "boss_damage_percent: 10%"
        },
        {
          "action": "싯포의 요술로 시선 분산",
          "consequence": "싯포가 요술을 부려 풍혈의 중심을 옮깁니다. 성공 시 플레이어의 체력 피해를 분산시키고 싯포의 도움으로 이동 속도를 얻습니다.",
          "card": "싯포",
          "effects": "move_speed: 10%, regeneration: 5%"
        }
      ],
      "followup": "성공 시 행동력 +2 / 실패 시 행동력 -3",
      "canonUse": "미륵의 풍혈이 생명력 흡수가 아닌 저주라는 사실을 정확히 반영.",
      "weakness": "미륵의 능력치 보너스(방어력)가 실제 전투에서 어느 정도의 생존력을 보장하는지 체감하기 어려울 수 있음."
    },
    {
      "title": "금사매 마을의 귀환과 불쥐의 수호",
      "situation": "여행자들의 거점인 금사매 마을에 도착했으나, 마을의 안정을 위협하는 외부의 적이 침입합니다. 가영이 입고 있는 '불쥐의 옷'이 외부의 사악한 기운을 튕겨내고 있지만, 기운이 약해지며 한계에 도달합니다.",
      "actions": [
        {
          "action": "불쥐의 옷 기운 강화",
          "consequence": "가영의 옷에 깃든 불쥐의 힘을 일시적으로 증폭시킵니다. 성공 시 다음 전투에서 플레이어의 보호막 수치가 증가합니다.",
          "card": "가영",
          "effects": "shielded_damage: 10%"
        },
        {
          "action": "금사매 마을 주민의 협조",
          "consequence": "마을 사람들에게 도움을 요청하여 적의 수적 우위를 상쇄합니다. 성공 시 다음 전투에서 동시에 등장하는 적의 수가 1 감소합니다.",
          "card": "금강",
          "effects": "event_choices: 1"
        },
        {
          "action": "철쇄아의 반응 유도",
          "consequence": "이누야샤의 마음을 자극하여 철쇄아를 공명시킵니다. 성공 시 다음 전투에서 치명타 확률이 증가합니다.",
          "card": "이누야샤",
          "effects": "crit_chance: 5%"
        }
      ],
      "followup": "성공 시 행동력 +1 / 실패 시 행동력 -1",
      "canonUse": "금사매 마을의 거점 기능 및 불쥐의 옷/철쇄아의 반응 설정을 활용.",
      "weakness": "이누야샤의 치명타 확률 보너스가 낮은 확률일 경우 유의미한 변수를 만들기 어려움."
    },
    {
      "title": "천생아의 부활과 셋쇼마루의 흔적",
      "situation": "과거 금강이 부활했던 장소 근처에서 셋쇼마루의 검 능력이 남아있는 기묘한 마력의 파편을 발견합니다. 이 파편을 획득하려 할 때, 파편이 플레이어의 의도를 시험하며 공격적인 마력을 방출합니다.",
      "actions": [
        {
          "action": "셋쇼마루의 검술 원리 분석",
          "consequence": "파편에 남은 검의 흔적을 분석하여 안전하게 추출합니다. 성공 시 다음 전투에서 방어력 관통력이 상승합니다.",
          "card": "묘가",
          "effects": "penetration: 10%"
        },
        {
          "action": "강제적인 마력 흡수",
          "consequence": "파편의 마력을 강제로 흡수하여 자신의 힘으로 전환합니다. 성공 시 대미지 증가를 얻지만, 다음 전투에서 치명타 피해 배율이 감소합니다.",
          "card": "이누야샤",
          "effects": "damage_percent: 10%, crit_damage: -5%"
        },
        {
          "action": "부활의 기운을 이용한 치유",
          "consequence": "금강의 부활 기운을 이용하여 파편의 마력을 중화합니다. 성공 시 다음 전투에서 초당 체력 재생량이 상승합니다.",
          "card": "금강",
          "effects": "regeneration: 8%"
        }
      ],
      "followup": "성공 시 행동력 +1 / 실패 시 행동력 -2",
      "canonUse": "금강의 부활과 셋쇼마루의 검 능력(천생아 관련)을 활용.",
      "weakness": "부활 기운을 통한 재생량이 초당 10% 상한에 걸릴 경우 효과가 상쇄될 가능성이 있음."
    }
  ]
}
